// rejectDuplicateMembers scans the raw submission and refuses the whole input
// if any single JSON object lists the same member name twice. ...
func rejectDuplicateMembers(data []byte) error {
	type frame struct {
		path     string
		keys     map[string]bool
		isObject bool
		wantKey  bool
		lastKey  string
		count    int
	}
	var stack []*frame
	closeValue := func() {
		if len(stack) == 0 {
			return
		}
		top := stack[len(stack)-1]
		if top.isObject {
			top.wantKey = true
		} else {
			top.count++
		}
	}
	childPath := func() string {
		if len(stack) == 0 {
			return ""
		}
		top := stack[len(stack)-1]
		if top.isObject {
			if top.path == "" {
				return top.lastKey
			}
			return top.path + "." + top.lastKey
		}
		return top.path + "[" + strconv.Itoa(top.count) + "]"
	}
	dec := json.NewDecoder(bytes.NewReader(data))
	for {
		tok, err := dec.Token()
		if err != nil {
			// io.EOF: fully scanned. Any syntax error is left for the real
			// decode below, which reports it as invalid JSON.
			return nil
		}
		switch t := tok.(type) {
		case json.Delim:
			switch t {
			case '{':
				stack = append(stack, &frame{path: childPath(), keys: make(map[string]bool), isObject: true, wantKey: true})
				closeValue()
			case '[':
				stack = append(stack, &frame{path: childPath(), isObject: false})
				closeValue()
			case '}', ']':
				stack = stack[:len(stack)-1]
				closeValue()
			}
		case string:
			if len(stack) > 0 && stack[len(stack)-1].isObject && stack[len(stack)-1].wantKey {
				top := stack[len(stack)-1]
				if top.keys[t] {
					where := top.path
					if where == "" {
						where = "the top-level object"
					} else {
						where = "object " + where
					}
					return errInvalid("duplicate member " + strconv.Quote(t) + " in " + where)
				}
				top.keys[t] = true
				top.wantKey = false
				top.lastKey = t
			} else {
				closeValue()
			}
		default:
			closeValue()
		}
	}
}
